CREATE TABLE IF NOT EXISTS tenants(tenant_id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'active',created_at TIMESTAMPTZ DEFAULT now());
INSERT INTO tenants(tenant_id,name,slug) VALUES(1,'Default Organization','default') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS users(user_id BIGSERIAL PRIMARY KEY,tenant_id BIGINT REFERENCES tenants(tenant_id),keycloak_sub TEXT UNIQUE,email TEXT,display_name TEXT,role TEXT DEFAULT 'user',locale TEXT DEFAULT 'en-US',currency TEXT DEFAULT 'USD',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS cases(case_id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL DEFAULT 1 REFERENCES tenants(tenant_id),case_number TEXT NOT NULL,court_name TEXT DEFAULT '',court_level TEXT NOT NULL DEFAULT 'federal',title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',stage TEXT DEFAULT '',metadata JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS case_parties(party_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE CASCADE,role TEXT NOT NULL,name TEXT NOT NULL,contact JSONB DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS docket_entries(docket_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE CASCADE,docket_number TEXT,title TEXT NOT NULL,entry_type TEXT DEFAULT 'filing',filed_at TIMESTAMPTZ,status TEXT DEFAULT 'filed',notes TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(document_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE SET NULL,title TEXT NOT NULL,document_type TEXT DEFAULT 'document',object_key TEXT DEFAULT '',sha256 TEXT DEFAULT '',mime_type TEXT DEFAULT '',size_bytes BIGINT DEFAULT 0,metadata JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS evidence_items(evidence_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE SET NULL,object_key TEXT NOT NULL,filename TEXT NOT NULL,sha256 TEXT NOT NULL,mime_type TEXT,size_bytes BIGINT DEFAULT 0,category TEXT DEFAULT 'general',provenance JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS transcripts(transcript_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE CASCADE,title TEXT NOT NULL,hearing_date DATE,transcript_type TEXT DEFAULT 'hearing',object_key TEXT DEFAULT '',missing_segments JSONB DEFAULT '[]'::jsonb,notes TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS research_items(research_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE SET NULL,citation TEXT DEFAULT '',title TEXT NOT NULL,court TEXT DEFAULT '',authority_type TEXT DEFAULT 'case',treatment TEXT DEFAULT 'background',notes TEXT DEFAULT '',url TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS drafts(draft_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE SET NULL,title TEXT NOT NULL,filing_type TEXT NOT NULL,body_markdown TEXT DEFAULT '',version INT DEFAULT 1,status TEXT DEFAULT 'draft',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks(task_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT DEFAULT '',status TEXT DEFAULT 'open',priority TEXT DEFAULT 'normal',due_at TIMESTAMPTZ,assignee TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS deadlines(deadline_id BIGSERIAL PRIMARY KEY,case_id BIGINT REFERENCES cases(case_id) ON DELETE CASCADE,title TEXT NOT NULL,due_at TIMESTAMPTZ NOT NULL,deadline_type TEXT DEFAULT 'filing',status TEXT DEFAULT 'open',notes TEXT DEFAULT '',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS alerts(alert_id BIGSERIAL PRIMARY KEY,tenant_id BIGINT DEFAULT 1 REFERENCES tenants(tenant_id),severity TEXT DEFAULT 'info',title TEXT NOT NULL,message TEXT DEFAULT '',entity_type TEXT DEFAULT '',entity_id TEXT DEFAULT '',read_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(audit_id BIGSERIAL PRIMARY KEY,tenant_id BIGINT DEFAULT 1,actor TEXT DEFAULT 'system',action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,meta JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_cases_number ON cases(case_number); CREATE INDEX IF NOT EXISTS idx_docket_case ON docket_entries(case_id); CREATE INDEX IF NOT EXISTS idx_documents_case ON documents(case_id); CREATE INDEX IF NOT EXISTS idx_evidence_case ON evidence_items(case_id); CREATE INDEX IF NOT EXISTS idx_tasks_case ON tasks(case_id); CREATE INDEX IF NOT EXISTS idx_deadlines_due ON deadlines(due_at);
